What does this program print?

```javascript
function size(n) {
  let label = "";
  switch (n) {
    case 1:
      label += "one ";
    case 2:
      label += "two ";
      break;
    case 3:
      label += "three ";
    default:
      label += "many";
  }
  return label.trim();
}
console.log(size(1), "|", size(3));
```

